int px(int n){return (int)std::lround(n*dpi);}
std::wstring text(HWND h){int n=GetWindowTextLengthW(h);std::wstring s(n+1,0);GetWindowTextW(h,&s[0],n+1);s.resize(n);return s;}
void setText(HWND h,const std::wstring& s){SetWindowTextW(h,s.c_str());}
std::wstring lower(std::wstring s){for(auto& c:s)c=towlower(c);return s;}
void message(HWND owner,const std::wstring& s,UINT flags=MB_OK|MB_ICONINFORMATION){MessageBoxW(owner,s.c_str(),L"Dijla — دجلة",flags|MB_RTLREADING);}
