std::wstring getDate(HWND h){SYSTEMTIME st{};DateTime_GetSystemtime(h,&st);wchar_t b[20];swprintf(b,20,L"%04u-%02u-%02u",st.wYear,st.wMonth,st.wDay);return b;}
void setDate(HWND h,const std::string& s){SYSTEMTIME st{};GetLocalTime(&st);unsigned y,m,d;if(sscanf(s.c_str(),"%u-%u-%u",&y,&m,&d)==3){st.wYear=(WORD)y;st.wMonth=(WORD)m;st.wDay=(WORD)d;}DateTime_SetSystemtime(h,GDT_VALID,&st);}
