    void choose(){if(!resolve())return;struct Search:Window{Store& s;std::string k;std::unique_ptr<Grid> grid;HWND q;Id result=0;Search(Store& st,std::string kind):Window(L"البحث عن قائمة",850,520),s(st),k(kind){}void pick(){result=grid->selected();if(result){accepted=true;close();}}void init()override{q=edit(20,20,810,L"",200,[&]{grid->filter(text(q));});grid=std::make_unique<Grid>(*this,20,64,810,386,[&]{pick();});Result r;r.columns={L"رقم القائمة",L"التاريخ",L"المستلم / المجهز"};std::map<Id,std::string> people;for(auto& p:s.t("person").rows)people[s.t("person").at(p,"p_no").i]=s.t("person").at(p,"p_name").s;for(auto it=s.t(k).rows.rbegin();it!=s.t(k).rows.rend();it++){auto& row=*it;r.ids.push_back(s.t(k).at(row,"shop_no").i);r.rows.push_back({wide(s.t(k).at(row,"menu_no").s),wide(s.t(k).at(row,"menu_date").s.substr(0,10)),wide(people[s.t(k).at(row,"custom_no").i])});}grid->set(std::move(r),{130,150,500});button(L"فتح",690,470,140,36,[&]{pick();},Right|Bottom);button(L"إلغاء",540,470,140,36,[&]{close();},Right|Bottom);}} search(s,kind);if(search.modal(h)){auto it=std::find(ids.begin(),ids.end(),search.result);if(it!=ids.end())load((int)(it-ids.begin()));}}
